-- M15 game question bank. Stable UUIDs and ON CONFLICT make this safe to
-- re-apply without replacing locally customized or previously revised rows.
begin;

insert into public.quiz_questions (
  id, category, difficulty, question, options, answer_index, explanation, version
)
select
  q.id, q.category, q.difficulty, q.question, q.options, q.answer_index,
  q.explanation, q.version
from jsonb_to_recordset($questions$[
  {"id":"10000000-0000-4000-8000-000000000001","category":"rukun_iman","difficulty":1,"question":"Menurut Sahih al-Bukhari 8, berapa prinsip yang menjadi dasar Islam?","options":["Lima","Empat","Enam","Tujuh"],"answer_index":0,"explanation":"Hadis tersebut menyebut lima prinsip: syahadat, salat, zakat, haji, dan puasa Ramadan. Sumber: Sahih al-Bukhari 8."},
  {"id":"10000000-0000-4000-8000-000000000002","category":"rukun_iman","difficulty":1,"question":"Manakah yang disebut sebagai rukun Islam dalam Sahih al-Bukhari 8?","options":["Membayar zakat","Berpuasa setiap Senin","Membangun masjid","Membaca seluruh hadis"],"answer_index":0,"explanation":"Membayar zakat termasuk lima prinsip Islam yang disebut dalam Sahih al-Bukhari 8."},
  {"id":"10000000-0000-4000-8000-000000000003","category":"rukun_iman","difficulty":1,"question":"Ibadah puasa yang disebut dalam lima prinsip Islam dilakukan pada bulan apa?","options":["Ramadan","Muharam","Rajab","Syawal"],"answer_index":0,"explanation":"Sahih al-Bukhari 8 menyebut puasa bulan Ramadan sebagai salah satu dari lima prinsip Islam."},
  {"id":"10000000-0000-4000-8000-000000000004","category":"rukun_iman","difficulty":2,"question":"Menurut hadis Jibril dalam Sahih Muslim 8a, iman mencakup kepercayaan kepada siapa?","options":["Allah, malaikat, kitab, rasul, hari akhir, dan takdir","Hanya Allah dan para rasul","Malaikat dan kitab saja","Allah, manusia, dan alam"],"answer_index":0,"explanation":"Sahih Muslim 8a menyebut iman kepada Allah, malaikat, kitab-kitab, rasul-rasul, hari akhir, serta takdir baik dan buruk."},
  {"id":"10000000-0000-4000-8000-000000000005","category":"rukun_iman","difficulty":2,"question":"Manakah yang secara eksplisit termasuk dalam enam perkara iman pada hadis Jibril?","options":["Hari akhir","Perdagangan","Keturunan","Perjalanan"],"answer_index":0,"explanation":"Hadis Jibril dalam Sahih Muslim 8a menyebut iman kepada hari akhir."},
  {"id":"10000000-0000-4000-8000-000000000006","category":"rukun_iman","difficulty":2,"question":"Beriman kepada kitab-kitab Allah termasuk dalam rukun apa menurut hadis Jibril?","options":["Iman","Islam saja","Ihsan saja","Adab"],"answer_index":0,"explanation":"Hadis Jibril dalam Sahih Muslim 8a memasukkan kitab-kitab Allah dalam perkara iman."},
  {"id":"10000000-0000-4000-8000-000000000007","category":"rukun_iman","difficulty":3,"question":"Dalam hadis Jibril, takdir yang disebut mencakup apa?","options":["Yang baik dan yang buruk","Masa lalu saja","Pilihan manusia saja","Peristiwa alam saja"],"answer_index":0,"explanation":"Sahih Muslim 8a menyebut iman kepada ketetapan Allah, yang baik maupun yang buruk."},
  {"id":"10000000-0000-4000-8000-000000000008","category":"rukun_iman","difficulty":3,"question":"Haji dalam lima prinsip Islam diwajibkan bagi orang yang bagaimana menurut Sahih Muslim 8a?","options":["Mampu menempuh perjalanan","Tinggal di Makkah","Berusia tertentu saja","Sudah pernah umrah"],"answer_index":0,"explanation":"Hadis Jibril menyebut haji ke Baitullah bagi yang mampu menanggung perjalanan. Sumber: Sahih Muslim 8a."},
  {"id":"10000000-0000-4000-8000-000000000009","category":"rukun_iman","difficulty":1,"question":"Kesaksian apa yang disebut pada awal lima prinsip Islam?","options":["Tiada sesembahan yang berhak disembah selain Allah dan Muhammad utusan Allah","Semua manusia memiliki agama yang sama","Setiap hari adalah hari raya","Semua perjalanan adalah ibadah haji"],"answer_index":0,"explanation":"Sahih al-Bukhari 8 menyebut kesaksian tauhid dan kerasulan Muhammad sebagai prinsip pertama."},
  {"id":"10000000-0000-4000-8000-000000000010","category":"rukun_iman","difficulty":1,"question":"Beriman kepada malaikat termasuk dalam daftar apa pada hadis Jibril?","options":["Perkara iman","Rukun haji","Syarat zakat","Bacaan salat"],"answer_index":0,"explanation":"Sahih Muslim 8a memasukkan iman kepada para malaikat dalam enam perkara iman."},

  {"id":"20000000-0000-4000-8000-000000000001","category":"sejarah_nabi","difficulty":1,"question":"Dalam Surah Yusuf 12:4, berapa bintang yang dilihat Yusuf dalam mimpinya?","options":["Sebelas","Sepuluh","Dua belas","Tujuh"],"answer_index":0,"explanation":"Yusuf menyebut sebelas bintang, matahari, dan bulan. Sumber: Al-Qur'an 12:4."},
  {"id":"20000000-0000-4000-8000-000000000002","category":"sejarah_nabi","difficulty":1,"question":"Siapa yang bersama Ibrahim meninggikan fondasi Baitullah menurut Al-Qur'an?","options":["Ismail","Musa","Dawud","Yusuf"],"answer_index":0,"explanation":"Al-Qur'an menyebut Ibrahim dan Ismail meninggikan fondasi Baitullah. Sumber: Al-Qur'an 2:127."},
  {"id":"20000000-0000-4000-8000-000000000003","category":"sejarah_nabi","difficulty":1,"question":"Kapal Nabi Nuh berlabuh di gunung apa menurut Al-Qur'an 11:44?","options":["Al-Judi","Uhud","Sinai","Arafat"],"answer_index":0,"explanation":"Ayat tersebut menyebut kapal itu berlabuh di Al-Judi. Sumber: Al-Qur'an 11:44."},
  {"id":"20000000-0000-4000-8000-000000000004","category":"sejarah_nabi","difficulty":2,"question":"Apa yang diperintahkan kepada Musa untuk dipukulkan ke laut sehingga terbelah?","options":["Tongkatnya","Jubahnya","Batu","Pohon"],"answer_index":0,"explanation":"Al-Qur'an menyebut Musa diperintahkan memukulkan tongkatnya ke laut, lalu laut terbelah. Sumber: Al-Qur'an 26:63."},
  {"id":"20000000-0000-4000-8000-000000000005","category":"sejarah_nabi","difficulty":2,"question":"Kitab apa yang disebut diberikan kepada Dawud?","options":["Zabur","Taurat","Injil","Suhuf Ibrahim"],"answer_index":0,"explanation":"Al-Qur'an menyebut Zabur diberikan kepada Dawud. Sumber: Al-Qur'an 4:163."},
  {"id":"20000000-0000-4000-8000-000000000006","category":"sejarah_nabi","difficulty":2,"question":"Kemampuan memahami bahasa apa yang disebut diberikan kepada Sulaiman?","options":["Bahasa burung","Bahasa Romawi","Bahasa Ibrani semua bangsa","Bahasa ikan"],"answer_index":0,"explanation":"Sulaiman berkata bahwa ia diajari bahasa burung. Sumber: Al-Qur'an 27:16."},
  {"id":"20000000-0000-4000-8000-000000000007","category":"sejarah_nabi","difficulty":2,"question":"Nabi Yunus ditelan oleh apa menurut Al-Qur'an 37:142?","options":["Ikan besar","Ular","Burung","Serigala"],"answer_index":0,"explanation":"Al-Qur'an menyebut seekor ikan menelannya ketika ia tercela. Sumber: Al-Qur'an 37:142."},
  {"id":"20000000-0000-4000-8000-000000000008","category":"sejarah_nabi","difficulty":3,"question":"Maryam diberi kabar gembira tentang kelahiran siapa?","options":["Isa Al-Masih","Yahya","Yusuf","Ismail"],"answer_index":0,"explanation":"Para malaikat menyampaikan kabar gembira tentang Al-Masih Isa putra Maryam. Sumber: Al-Qur'an 3:45."},
  {"id":"20000000-0000-4000-8000-000000000009","category":"sejarah_nabi","difficulty":3,"question":"Siapakah yang disebut sebagai penutup para nabi dalam Al-Qur'an 33:40?","options":["Muhammad","Isa","Musa","Ibrahim"],"answer_index":0,"explanation":"Al-Qur'an 33:40 menyebut Muhammad sebagai Rasul Allah dan penutup para nabi."},
  {"id":"20000000-0000-4000-8000-000000000010","category":"sejarah_nabi","difficulty":1,"question":"Ayah Nabi Yusuf menasihatinya agar tidak menceritakan mimpinya kepada siapa?","options":["Saudara-saudaranya","Penduduk Mesir","Para pedagang","Para penggembala"],"answer_index":0,"explanation":"Ya'qub menasihati Yusuf agar tidak menceritakan mimpinya kepada saudara-saudaranya. Sumber: Al-Qur'an 12:5."},

  {"id":"30000000-0000-4000-8000-000000000001","category":"fikih_dasar","difficulty":1,"question":"Bagian tubuh mana yang disebut dibasuh dalam wudu pada Al-Qur'an 5:6?","options":["Wajah","Punggung","Dada","Lutut"],"answer_index":0,"explanation":"Al-Qur'an 5:6 menyebut membasuh wajah, lengan sampai siku, mengusap kepala, dan membasuh kaki sampai mata kaki."},
  {"id":"30000000-0000-4000-8000-000000000002","category":"fikih_dasar","difficulty":1,"question":"Sampai bagian mana lengan dibasuh dalam wudu menurut Al-Qur'an 5:6?","options":["Siku","Bahu","Pergelangan saja","Jari saja"],"answer_index":0,"explanation":"Al-Qur'an 5:6 menyebut membasuh lengan sampai siku."},
  {"id":"30000000-0000-4000-8000-000000000003","category":"fikih_dasar","difficulty":1,"question":"Apa yang dilakukan terhadap kepala dalam wudu menurut Al-Qur'an 5:6?","options":["Diusap","Dibasuh tiga kali secara eksplisit","Ditutup","Tidak disebut"],"answer_index":0,"explanation":"Al-Qur'an 5:6 menyebut mengusap kepala. Rincian praktik fikih dapat memiliki penjelasan lebih lanjut."},
  {"id":"30000000-0000-4000-8000-000000000004","category":"fikih_dasar","difficulty":2,"question":"Jika tidak menemukan air dalam keadaan yang disebut Al-Qur'an 5:6, apa yang ditunjukkan ayat sebagai pengganti bersuci?","options":["Tayammum dengan tanah yang suci","Tidak perlu bersuci selamanya","Mandi dengan pasir","Mengulang perjalanan"],"answer_index":0,"explanation":"Ayat tersebut memberi keringanan untuk mengusap wajah dan tangan dengan tanah yang suci ketika air tidak tersedia. Sumber: Al-Qur'an 5:6."},
  {"id":"30000000-0000-4000-8000-000000000005","category":"fikih_dasar","difficulty":1,"question":"Puasa diwajibkan kepada orang beriman dengan tujuan agar mereka menjadi apa menurut Al-Qur'an 2:183?","options":["Bertakwa","Kaya","Terkenal","Selalu bepergian"],"answer_index":0,"explanation":"Al-Qur'an 2:183 menyatakan puasa diwajibkan agar orang beriman bertakwa."},
  {"id":"30000000-0000-4000-8000-000000000006","category":"fikih_dasar","difficulty":2,"question":"Ke arah mana umat Islam diperintahkan menghadapkan wajah ketika salat dalam Al-Qur'an 2:144?","options":["Masjidil Haram","Gunung Sinai","Masjid Nabawi saja","Matahari terbit"],"answer_index":0,"explanation":"Al-Qur'an 2:144 memerintahkan menghadap ke arah Masjidil Haram."},
  {"id":"30000000-0000-4000-8000-000000000007","category":"fikih_dasar","difficulty":2,"question":"Apa yang diperintahkan saat seruan salat Jumat disampaikan dalam Al-Qur'an 62:9?","options":["Bersegera mengingat Allah dan meninggalkan jual beli","Melanjutkan jual beli","Memulai perjalanan jauh","Menunda salat"],"answer_index":0,"explanation":"Al-Qur'an 62:9 memerintahkan bersegera mengingat Allah dan meninggalkan jual beli ketika seruan Jumat disampaikan."},
  {"id":"30000000-0000-4000-8000-000000000008","category":"fikih_dasar","difficulty":3,"question":"Safa dan Marwah disebut dalam Al-Qur'an 2:158 sebagai apa?","options":["Sebagian syiar Allah","Nama dua nabi","Dua bulan hijriah","Dua kitab"],"answer_index":0,"explanation":"Ayat tersebut menyebut Safa dan Marwah sebagai sebagian syiar Allah."},
  {"id":"30000000-0000-4000-8000-000000000009","category":"fikih_dasar","difficulty":3,"question":"Di antara hal yang dilarang selama haji menurut Al-Qur'an 2:197 adalah apa?","options":["Perkataan keji, kefasikan, dan perdebatan","Membaca Al-Qur'an","Berdoa","Mengingat Allah"],"answer_index":0,"explanation":"Al-Qur'an 2:197 menyebut tidak berkata keji, berbuat fasik, atau berbantah-bantahan dalam haji."},
  {"id":"30000000-0000-4000-8000-000000000010","category":"fikih_dasar","difficulty":2,"question":"Menurut Al-Qur'an 3:97, siapa yang berkewajiban menunaikan haji ke Baitullah?","options":["Orang yang mampu mengadakan perjalanan ke sana","Semua anak kecil","Hanya penduduk Makkah","Setiap orang setiap tahun"],"answer_index":0,"explanation":"Al-Qur'an 3:97 menyebut kewajiban haji bagi manusia yang mampu mengadakan perjalanan ke Baitullah."},

  {"id":"40000000-0000-4000-8000-000000000001","category":"umum","difficulty":1,"question":"Dalam bahasa apa Al-Qur'an disebut diturunkan dalam Surah Yusuf 12:2?","options":["Bahasa Arab","Bahasa Ibrani","Bahasa Yunani","Bahasa Latin"],"answer_index":0,"explanation":"Al-Qur'an 12:2 menyatakan bahwa Al-Qur'an diturunkan dalam bahasa Arab."},
  {"id":"40000000-0000-4000-8000-000000000002","category":"umum","difficulty":1,"question":"Bulan apa yang disebut sebagai bulan diturunkannya Al-Qur'an dalam Al-Qur'an 2:185?","options":["Ramadan","Syawal","Safar","Dzulqa'dah"],"answer_index":0,"explanation":"Al-Qur'an 2:185 menyebut bulan Ramadan sebagai bulan diturunkannya Al-Qur'an."},
  {"id":"40000000-0000-4000-8000-000000000003","category":"umum","difficulty":1,"question":"Surah apa yang dimulai dengan pernyataan bahwa Allah Maha Esa?","options":["Al-Ikhlas","Al-Fil","Al-Kautsar","Al-Ma'un"],"answer_index":0,"explanation":"Surah Al-Ikhlas 112:1 dimulai dengan pernyataan keesaan Allah."},
  {"id":"40000000-0000-4000-8000-000000000004","category":"umum","difficulty":2,"question":"Menurut Al-Qur'an 97:3, malam kemuliaan lebih baik daripada berapa bulan?","options":["Seribu bulan","Seratus bulan","Sepuluh bulan","Dua belas bulan"],"answer_index":0,"explanation":"Al-Qur'an 97:3 menyebut malam kemuliaan lebih baik daripada seribu bulan."},
  {"id":"40000000-0000-4000-8000-000000000005","category":"umum","difficulty":2,"question":"Ayat Kursi terdapat pada surah dan ayat berapa?","options":["Al-Baqarah 2:255","Al-Fatihah 1:1","Al-Ikhlas 112:1","An-Nas 114:6"],"answer_index":0,"explanation":"Ayat yang dikenal sebagai Ayat Kursi adalah Al-Qur'an 2:255."},
  {"id":"40000000-0000-4000-8000-000000000006","category":"umum","difficulty":2,"question":"Al-Qur'an 7:54 menyebut penciptaan langit dan bumi berlangsung dalam berapa hari?","options":["Enam hari","Tujuh hari","Dua belas hari","Empat puluh hari"],"answer_index":0,"explanation":"Al-Qur'an 7:54 menyebut penciptaan langit dan bumi dalam enam hari."},
  {"id":"40000000-0000-4000-8000-000000000007","category":"umum","difficulty":2,"question":"Surah apa yang ayat pertamanya bersumpah demi masa?","options":["Al-'Asr","Al-Falaq","Al-Qadr","Al-Kafirun"],"answer_index":0,"explanation":"Surah Al-'Asr 103:1 dimulai dengan sumpah demi masa."},
  {"id":"40000000-0000-4000-8000-000000000008","category":"umum","difficulty":3,"question":"Surah mana yang memohon perlindungan kepada Tuhan manusia?","options":["An-Nas","Al-Kafirun","Al-Masad","Al-Qari'ah"],"answer_index":0,"explanation":"Surah An-Nas 114:1 memulai permohonan perlindungan kepada Tuhan manusia."},
  {"id":"40000000-0000-4000-8000-000000000009","category":"umum","difficulty":3,"question":"Surah Al-Kautsar terdiri dari berapa ayat dalam mushaf standar?","options":["Tiga","Lima","Tujuh","Sepuluh"],"answer_index":0,"explanation":"Surah Al-Kautsar adalah surah ke-108 dan terdiri dari tiga ayat."},
  {"id":"40000000-0000-4000-8000-000000000010","category":"umum","difficulty":1,"question":"Surah pembuka dalam urutan mushaf adalah surah apa?","options":["Al-Fatihah","Al-Baqarah","Al-Ikhlas","An-Nas"],"answer_index":0,"explanation":"Al-Fatihah adalah surah pertama pada urutan mushaf Al-Qur'an."}
]$questions$::jsonb) as q(
  id uuid,
  category text,
  difficulty integer,
  question text,
  options jsonb,
  answer_index integer,
  explanation text,
  version integer
)
on conflict (id) do nothing;

commit;
